<?php

/* The Divine Lands - separate Client Handling module.

   Client base: data.id. Handling: client_updates(cid,status,grade,notes,serious,open_client). */

if(!headers_sent()&&function_exists('ob_gzhandler'))ob_start('ob_gzhandler');

$con=@mysqli_connect('localhost','root','','tdl'); if(!$con) die('Database connection failed: '.mysqli_connect_error()); mysqli_set_charset($con,'utf8mb4');

function e($v){return htmlspecialchars((string)($v??''),ENT_QUOTES,'UTF-8');}

function jr($ok,$a=[],$code=200){http_response_code($code);header('Content-Type: application/json; charset=utf-8');echo json_encode(array_merge(['ok'=>$ok],$a),JSON_UNESCAPED_UNICODE|JSON_UNESCAPED_SLASHES);exit;}

$statuses=['New','Contacted','Interested','Requirement Received','Property Shared','Site Visit Planned','Site Visit Done','Negotiation','Follow-up','On Hold','Converted','Not Interested','Closed'];
$grades=['Select Grade','A+','A','B','C','D'];

$action=$_GET['action']??$_POST['action']??'';

if($action==='search_clients'){

$q=trim((string)($_GET['q']??'')); if(strlen($q)<2)jr(true,['clients'=>[]]); $x='%'.$q.'%';

$sql="SELECT d.id,d.name,d.company_name,d.scheme_name,d.number1,d.number2,d.number3,d.area,CASE WHEN cu.cid IS NULL THEN 0 ELSE 1 END is_active,cu.status,cu.serious FROM data d LEFT JOIN client_updates cu ON cu.cid=d.id WHERE d.name LIKE ? OR d.company_name LIKE ? OR d.scheme_name LIKE ? OR d.number1 LIKE ? OR d.number2 LIKE ? OR d.number3 LIKE ? OR d.area LIKE ? ORDER BY d.name ASC,d.id ASC LIMIT 60";

$s=mysqli_prepare($con,$sql);if(!$s)jr(false,['error'=>mysqli_error($con)],500);mysqli_stmt_bind_param($s,'sssssss',$x,$x,$x,$x,$x,$x,$x);mysqli_stmt_execute($s);$r=mysqli_stmt_get_result($s);$out=[];while($v=mysqli_fetch_assoc($r))$out[]=$v;mysqli_stmt_close($s);jr(true,['clients'=>$out]);}

if($action==='add_client'){

$cid=(int)($_POST['cid']??0);if($cid<1)jr(false,['error'=>'Invalid client.'],400);

$s=mysqli_prepare($con,'SELECT id FROM data WHERE id=? LIMIT 1');mysqli_stmt_bind_param($s,'i',$cid);mysqli_stmt_execute($s);$r=mysqli_stmt_get_result($s);if(!mysqli_fetch_assoc($r)){mysqli_stmt_close($s);jr(false,['error'=>'Client was not found in the client base.'],404);}mysqli_stmt_close($s);

$s=mysqli_prepare($con,'SELECT id FROM client_updates WHERE cid=? LIMIT 1');mysqli_stmt_bind_param($s,'i',$cid);mysqli_stmt_execute($s);$r=mysqli_stmt_get_result($s);if(mysqli_fetch_assoc($r)){mysqli_stmt_close($s);jr(false,['error'=>'This client is already Active.'],409);}mysqli_stmt_close($s);

$status='New';$grade='B';$notes='';$serious=0;$open_client=0;$s=mysqli_prepare($con,'INSERT INTO client_updates(cid,status,grade,notes,serious,open_client) VALUES(?,?,?,?,?,?)');if(!$s)jr(false,['error'=>mysqli_error($con)],500);mysqli_stmt_bind_param($s,'isssii',$cid,$status,$grade,$notes,$serious,$open_client);if(!mysqli_stmt_execute($s)){$e=mysqli_stmt_error($s);mysqli_stmt_close($s);jr(false,['error'=>$e],500);}mysqli_stmt_close($s);jr(true,['message'=>'Client added.']);}

if($action==='update_client'){

$id=(int)($_POST['id']??0);$status=trim((string)($_POST['status']??''));$grade=trim((string)($_POST['grade']??'B'));$serious=!empty($_POST['serious'])?1:0;$open_client=!empty($_POST['open_client'])?1:0;if($id<1||!in_array($status,$statuses,true)||!in_array($grade,$grades,true))jr(false,['error'=>'Invalid update.'],400);$s=mysqli_prepare($con,'UPDATE client_updates SET status=?,grade=?,serious=?,open_client=? WHERE id=?');if(!$s)jr(false,['error'=>mysqli_error($con)],500);mysqli_stmt_bind_param($s,'ssiii',$status,$grade,$serious,$open_client,$id);$ok=mysqli_stmt_execute($s);$er=mysqli_stmt_error($s);mysqli_stmt_close($s);if(!$ok)jr(false,['error'=>$er],500);jr(true,['message'=>'Updated.']);}

if($action==='add_note'){

$id=(int)($_POST['id']??0);$note=trim((string)($_POST['note']??''));if($id<1||$note==='')jr(false,['error'=>'Please enter a note.'],400);$old='';$found=false;$s=mysqli_prepare($con,'SELECT notes FROM client_updates WHERE id=? LIMIT 1');mysqli_stmt_bind_param($s,'i',$id);mysqli_stmt_execute($s);$r=mysqli_stmt_get_result($s);if($v=mysqli_fetch_assoc($r)){$found=true;$old=trim((string)$v['notes']);}mysqli_stmt_close($s);if(!$found)jr(false,['error'=>'Active client not found.'],404);$entry='['.date('d M Y, h:i A')."]\n".$note;$notes=$old===''?$entry:$entry."\n\n".$old;$s=mysqli_prepare($con,'UPDATE client_updates SET notes=? WHERE id=?');if(!$s)jr(false,['error'=>mysqli_error($con)],500);mysqli_stmt_bind_param($s,'si',$notes,$id);$ok=mysqli_stmt_execute($s);$er=mysqli_stmt_error($s);mysqli_stmt_close($s);if(!$ok)jr(false,['error'=>$er],500);jr(true,['message'=>'Note added.']);}

if($action==='remove_client'){$id=(int)($_POST['id']??0);$s=mysqli_prepare($con,'DELETE FROM client_updates WHERE id=?');if(!$s)jr(false,['error'=>mysqli_error($con)],500);mysqli_stmt_bind_param($s,'i',$id);$ok=mysqli_stmt_execute($s);$er=mysqli_stmt_error($s);mysqli_stmt_close($s);if(!$ok)jr(false,['error'=>$er],500);jr(true,['message'=>'Removed from Active Clients.']);}



$active=[];$sql="SELECT cu.id update_id,cu.cid,cu.status,cu.grade,cu.notes,cu.serious,cu.open_client,d.name,d.company_name,d.scheme_name,d.number1,d.number2,d.number3,d.area FROM client_updates cu INNER JOIN data d ON d.id=cu.cid ORDER BY cu.serious DESC,cu.id DESC";$r=mysqli_query($con,$sql);if($r)while($v=mysqli_fetch_assoc($r))$active[]=$v;

$counts=array_fill_keys($statuses,0);$seriousCount=0;$openClientCount=0;foreach($active as $v){if(isset($counts[$v['status']]))$counts[$v['status']]++;if((int)$v['serious'])$seriousCount++;if((int)$v['open_client'])$openClientCount++;}

$areas=[];foreach($active as $v){foreach(preg_split('/\s*,\s*/',(string)$v['area']) as $a){$a=trim($a);if($a!==''&&!in_array($a,$areas,true))$areas[]=$a;}}natcasesort($areas);$areas=array_values($areas);

?>

