t-size:12px;color:var(--muted);margin-top:4px}.searchbox{position:relative}.search{width:100%;border:1px solid var(--line);border-radius:13px;padding:13px 15px;outline:0;background:#fafbfd}.search:focus,.select:focus,textarea:focus{border-color:#75bd98;box-shadow:0 0 0 4px #15995712}.results{display:none;position:absolute;left:0;right:0;top:53px;z-index:30;background:#fff;border:1px solid var(--line);border-radius:16px;box-shadow:0 22px 55px #10203826;max-height:400px;overflow:auto}.result{padding:13px 15px;border-bottom:1px solid #eef1f5;display:flex;justify-content:space-between;align-items:center;gap:15px}.result:last-child{border:0}.rname{font-weight:850}.rmeta{font-size:12px;color:var(--muted);margin-top:3px}.tablewrap{overflow:auto;border:1px solid var(--line);border-radius:16px}.table{border-collapse:separate;border-spacing:0;width:100%;min-width:1100px}.table th{background:#f8fafc;color:#697386;text-align:left;font-size:11px;text-transform:uppercase;letter-spacing:.06em;padding:12px;border-bottom:1px solid var(--line)}.table td{padding:13px;border-bottom:1px solid #eef1f5;vertical-align:top}.table tr:last-child td{border:0}.name{font-weight:850}.muted{color:var(--muted);font-size:12px;margin-top:4px}.wa{color:#13834b;text-decoration:none;font-weight:750}.select{border:1px solid var(--line);border-radius:10px;padding:8px;background:#fff;font-weight:750;min-width:165px}.serious{font-size:12px;font-weight:800;color:#c7373c;white-space:nowrap}.serious input{accent-color:#d83b43}.open-client{font-size:12px;font-weight:800;color:#117441;white-space:nowrap}.open-client input{accent-color:#159957}.filterbar{display:grid;grid-template-columns:minmax(240px,1.7fr) minmax(160px,.8fr) minmax(160px,.8fr) auto auto;gap:9px;margin-bottom:12px}.filter-search,.filter-select{border:1px solid var(--line);border-radius:11px;padding:10px 12px;background:#fff;outline:0}.filter-search:focus,.filter-select:focus{border-color:#75bd98;box-shadow:0 0 0 4px #15995712}.toggle-filter{border:1px solid var(--line);background:#fff;color:#5d6878;border-radius:11px;padding:9px 12px;font-weight:800;cursor:pointer}.toggle-filter.on{background:#eaf8f0;border-color:#a9d9bd;color:#117441}.filter-count{font-size:12px;color:var(--muted);margin:2px 0 12px}.clear-filter{border:0;background:#f0f3f7;color:#344054;border-radius:11px;padding:9px 12px;font-weight:800;cursor:pointer}.notes{max-width:340px;max-height:115px;overflow:auto;white-space:pre-wrap;color:#3f4b5d;font-size:12px;line-height:1.55;background:#f8fafc;border:1px solid #edf1f5;border-radius:11px;padding:10px}.note-empty{color:#9aa3b1;font-style:italic}.note-actions{display:flex;gap:6px;flex-wrap:wrap;margin-top:7px}.note-btn{border:1px solid #dce5df;background:#f6fbf8;color:#117441;border-radius:9px;padding:6px 9px;font-size:11px;font-weight:800;cursor:pointer}.filters{display:flex;gap:7px;flex-wrap:wrap;margin-bottom:14px}.filter{border:1px solid var(--line);background:#fff;color:#5d6878;border-radius:10px;padding:8px 11px;font-weight:750;cursor:pointer}.filter.on{background:#eaf8f0;border-color:#a9d9bd;color:#117441}.empty{text-align:center;padding:55px 20px;color:var(--muted)}.empty b{display:block;color:var(--txt);font-size:18px;margin-bottom:4px}.modalbg{position:fixed;inset:0;background:#09132199;backdrop-filter:blur(6px);display:none;align-items:center;justify-content:center;padding:18px;z-index:100}.modal{background:#fff;width:min(650px,100%);border-radius:23px;overflow:hidden;box-shadow:0 30px 90px #0004}.mh{padding:19px 21px;border-bottom:1px solid var(--line);display:flex;justify-content:space-between}.mh h3{margin:0}.close{border:0;background:#eff2f5;border-radius:9px;width:35px;height:35px;font-size:20px;cursor:pointer}.mb{padding:20px}.mb textarea{width:100%;min-height:190px;border:1px solid var(--line);border-radius:13px;padding:13px;outline:0;resize:vertical}.mf{padding:14px 20px;border-top:1px solid var(--line);background:#fafbfd;text-align:right}.toast{position:fixed;right:20px;bottom:20px;display:none;padding:13px 16px;border-radius:12px;color:#fff;background:#172033;z-index:200;font-weight:750}.toast.ok{background:#137743}.toast.bad{background:#c7383e}@media(max-width:1100px){.stats{grid-template-columns:repeat(4,1fr)}.filterbar{grid-template-columns:1fr 1fr 1fr}.filterbar .clear-filter{grid-column:span 1}}@media(max-width:750px){.filterbar{grid-template-columns:1fr 1fr}.filterbar .filter-search{grid-column:1/-1}}@media(max-width:650px){.wrap{padding:17px 11px 40px}.top .btn{display:none}.hero h2{font-size:24px}.stats{grid-template-columns:repeat(2,1fr)}.panel{padding:14px}}

