<?php if(!$active): ?><div class="empty"><b>No active clients yet</b>Select a client from the existing client base above.</div><?php else: ?><table class="table" id="ct"><thead><tr><th>Client</th><th>Contact</th><th>Requirement / Area</th><th>Status</th><th>Grade</th><th>Serious</th><th>Open Client</th><th>Notes</th><th>Action</th></tr></thead><tbody>

<?php foreach($active as $c): ?><tr data-status="<?=e($c['status'])?>" data-search="<?=e(trim($c['name'].' '.$c['company_name'].' '.$c['scheme_name'].' '.$c['number1'].' '.$c['number2'].' '.$c['number3'].' '.$c['area']))?>" data-area="<?=e($c['area'])?>" data-serious="<?=$c['serious']?1:0?>" data-open="<?=$c['open_client']?1:0?>"><td><div class="name"><?=e($c['name'])?></div><div class="muted"><?=e($c['company_name'])?><?=trim($c['scheme_name'])?' · '.e($c['scheme_name']):''?></div></td><td><?php foreach([$c['number1'],$c['number2'],$c['number3']] as $n): if(trim((string)$n)!==''):$wa=preg_replace('/[^0-9]/','',(string)$n);?><div><a class="wa" target="_blank" rel="noopener" href="https://wa.me/<?=e($wa)?>"><?=e($n)?></a></div><?php endif;endforeach;?></td><td><?=e($c['area'])?><div class="muted"><?=e($c['scheme_name'])?></div></td><td><select class="select" data-id="<?=$c['update_id']?>" onchange="saveClient(this)"><?php foreach($statuses as $s):?><option <?= $c['status']===$s?'selected':''?>><?=e($s)?></option><?php endforeach;?></select></td><td><select class="select grade-select" data-id="<?=$c['update_id']?>" onchange="saveClient(this)"><?php foreach($grades as $g):?><option <?= (($c['grade']??'B')===$g)?'selected':''?>><?=e($g)?></option><?php endforeach;?></select></td><td><label class="serious"><input type="checkbox" data-id="<?=$c['update_id']?>" <?=$c['serious']?'checked':''?> onchange="saveSerious(this)"> Serious</label></td><td><label class="open-client"><input type="checkbox" data-id="<?=$c['update_id']?>" <?=$c['open_client']?'checked':''?> onchange="saveOpenClient(this)"> Open Client</label></td><td><div class="notes"><?=trim((string)$c['notes'])!==''?e($c['notes']):'<span class="note-empty">No notes yet.</span>'?></div><div class="note-actions"><button class="note-btn" onclick='openNote(<?=$c['update_id']?>,<?=json_encode($c['name'],JSON_HEX_TAG|JSON_HEX_APOS|JSON_HEX_QUOT|JSON_HEX_AMP)?>,<?=json_encode((string)$c['notes'],JSON_HEX_TAG|JSON_HEX_APOS|JSON_HEX_QUOT|JSON_HEX_AMP)?>)'>＋ Add Note</button><button class="note-btn" onclick='viewNotes(<?=json_encode((string)$c['notes'],JSON_HEX_TAG|JSON_HEX_APOS|JSON_HEX_QUOT|JSON_HEX_AMP)?>,<?=json_encode($c['name'],JSON_HEX_TAG|JSON_HEX_APOS|JSON_HEX_QUOT|JSON_HEX_AMP)?>)'>View History</button></div></td><td><button class="btn danger" onclick="removeClient(<?=$c['update_id']?>)">Remove</button></td></tr><?php endforeach;?></tbody></table><?php endif;?></div></section>

</div>

<div class="modalbg" id="modal"><div class="modal"><div class="mh"><div><h3 id="mt">Add Note</h3><div class="sub">The new note will be added above the previous history.</div></div><button class="close" onclick="closeNote()">×</button></div><div class="mb"><div id="history" style="display:none;margin-bottom:14px;background:#f8fafc;border:1px solid #e6ebf1;border-radius:13px;padding:13px;max-height:260px;overflow:auto;white-space:pre-wrap;font-size:12px;line-height:1.6;color:#475467"></div><textarea id="note" placeholder="Write follow-up details, requirement, site visit, price discussion, next action…"></textarea></div><div class="mf"><button class="btn light" onclick="closeNote()">Cancel</button> <button class="btn primary" onclick="saveNote()">Save Note</button></div></div></div><div class="toast" id="toast"></div>

<script>

const ep=location.pathname, statuses=<?=json_encode(array_merge(['All'],$statuses),JSON_UNESCAPED_UNICODE)?>;let noteId=0,filter='All';

function esc(v){return String(v??'').replace(/[&<>"']/g,m=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#039;'}[m]))}function toast(m,ok=true){let t=document.getElementById('toast');t.textContent=m;t.className='toast '+(ok?'ok':'bad');t.style.display='block';clearTimeout(window.tt);window.tt=setTimeout(()=>t.style.display='none',2400)}function focusSearch(){let x=document.getElementById('search');x.focus();x.scrollIntoView({behavior:'smooth',block:'center'})}

function post(action,data){data=data||{};data.action=action;return fetch(ep,{method:'POST',headers:{'Content-Type':'application/x-www-form-urlencoded;charset=UTF-8'},body:new URLSearchParams(data)}).then(r=>r.json()).then(x=>{if(!x.ok)throw Error(x.error||'Request failed');return x})}

const search=document.getElementById('search'),results=document.getElementById('results');let st;search.addEventListener('input',()=>{clearTimeout(st);let q=search.value.trim();if(q.length<2){results.style.display='none';return}st=setTimeout(()=>find(q),220)});document.addEventListener('click',e=>{if(!e.target.closest('.searchbox'))results.style.display='none'});

function find(q){fetch(ep+'?action=search_clients&q='+encodeURIComponent(q)).then(r=>r.json()).then(x=>{results.innerHTML='';if(!x.clients.length){results.innerHTML='<div class="empty" style="padding:25px">No client found.</div>';results.style.display='block';return}x.clients.forEach(c=>{let row=document.createElement('div');row.className='result';row.innerHTML='<div><div class="rname">'+esc(c.name||'Unnamed')+'</div><div class="rmeta">'+esc(c.company_name||'')+(c.scheme_name?' · '+esc(c.scheme_name):'')+(c.area?' · '+esc(c.area):'')+'</div></div>';let b=document.createElement('button');b.className='btn '+(+c.is_active?'light':'primary');b.textContent=+c.is_active?'Already Active':'＋ Add';b.disabled=+c.is_active;b.onclick=()=>addClient(c.id);row.appendChild(b);results.appendChild(row)});results.style.display='block'}).catch(()=>{})}

function addClient(id){post('add_client',{cid:id}).then(()=>{toast('Client added');location.reload()}).catch(e=>toast(e.message,false))}

function saveClient(s){let row=s.closest('tr');let statusSelect=row.querySelector('select[data-id].select:not(.grade-select)');let gradeSelect=row.querySelector('.grade-select');let checks=row.querySelectorAll('input[type=checkbox]');let serious=checks[0];let open=checks[1];post('update_client',{id:s.dataset.id,status:statusSelect.value,grade:gradeSelect.value,serious:serious.checked?'1':'0',open_client:open.checked?'1':'0'}).then(()=>{row.dataset.status=statusSelect.value;applyClientFilters();toast(s.classList.contains('grade-select')?'Grade updated':'Status updated')}).catch(e=>toast(e.message,false))}

function saveSerious(b){let row=b.closest('tr'),s=row.querySelector('.select'),open=row.querySelectorAll('input[type=checkbox]')[1];post('update_client',{id:b.dataset.id,status:s.value,grade:row.querySelector('.grade-select').value,serious:b.checked?'1':'0',open_client:open.checked?'1':'0'}).then(()=>{row.dataset.serious=b.checked?'1':'0';applyClientFilters();toast(b.checked?'Marked serious':'Serious flag removed')}).catch(e=>toast(e.message,false))}

function saveOpenClient(b){let row=b.closest('tr'),s=row.querySelector('.select'),serious=row.querySelectorAll('input[type=checkbox]')[0];post('update_client',{id:b.dataset.id,status:s.value,grade:row.querySelector('.grade-select').value,serious:serious.checked?'1':'0',open_client:b.checked?'1':'0'}).then(()=>{row.dataset.open=b.checked?'1':'0';applyClientFilters();toast(b.checked?'Marked open client':'Open client flag removed')}).catch(e=>toast(e.message,false))}

function openNote(id,name,history){noteId=id;document.getElementById('mt').textContent='Notes · '+name;document.getElementById('history').style.display=history&&history.trim()?'block':'none';document.getElementById('history').textContent=history&&history.trim()?history:'No previous notes yet.';document.getElementById('note').value='';document.getElementById('modal').style.display='flex';setTimeout(()=>document.getElementById('note').focus(),50)} function viewNotes(history,name){noteId=0;document.getElementById('mt').textContent='Note History · '+name;document.getElementById('history').style.display='block';document.getElementById('history').textContent=history&&history.trim()?history:'No notes yet.';document.getElementById('note').style.display='none';document.getElementById('modal').style.display='flex';document.querySelector('#modal .mf').innerHTML='<button class="btn light" onclick="closeNote()">Close</button>'}function closeNote(){document.getElementById('modal').style.display='none';noteId=0;document.getElementById('note').style.display='block';document.getElementById('history').style.display='none';document.querySelector('#modal .mf').innerHTML='<button class="btn light" onclick="closeNote()">Cancel</button> <button class="btn primary" onclick="saveNote()">Save Note</button>'}function saveNote(){let n=document.getElementById('note').value.trim();if(!n)return toast('Please enter a note.',false);post('add_note',{id:noteId,note:n}).then(()=>{toast('Note saved');closeNote();location.reload()}).catch(e=>toast(e.message,false))}function removeClient(id){if(!confirm('Remove this client from Active Clients? The original client base record will NOT be deleted.'))return;post('remove_client',{id:id}).then(()=>{toast('Removed from Active Clients');location.reload()}).catch(e=>toast(e.message,false))}

let flagFilters={serious:false,open:false};

const cfs=document.getElementById('clientFilterSearch'), af=document.getElementById('areaFilter'), sf=document.getElementById('statusFilter');

[cfs,af,sf].forEach(x=>x.addEventListener('input',applyClientFilters));

function normalizeFilter(v){return String(v||'').toLowerCase().trim()}

function rowMatchesSearch(row,q){if(!q)return true;let text=normalizeFilter(row.dataset.search||row.textContent||'');return q.split(/\s+/).filter(Boolean).every(word=>text.indexOf(word)!==-1)}

function applyClientFilters(){let q=normalizeFilter(cfs.value),area=normalizeFilter(af.value),status=normalizeFilter(sf.value),rows=document.querySelectorAll('#ct tbody tr'),shown=0;rows.forEach(row=>{let rowArea=normalizeFilter(row.dataset.area),rowStatus=normalizeFilter(row.dataset.status);let ok=rowMatchesSearch(row,q)&&( !area || rowArea.split(',').map(normalizeFilter).includes(area) )&&( !status || rowStatus===status )&&(!flagFilters.serious||row.dataset.serious==='1')&&(!flagFilters.open||row.dataset.open==='1');row.style.display=ok?'':'none';if(ok)shown++});let count=document.getElementById('filterCount');if(count)count.textContent=shown+' of '+rows.length+' active clients shown';document.getElementById('seriousFilter').classList.toggle('on',flagFilters.serious);document.getElementById('openFilter').classList.toggle('on',flagFilters.open)}

function toggleFlagFilter(flag){flagFilters[flag]=!flagFilters[flag];applyClientFilters()}

function clearClientFilters(){cfs.value='';af.value='';sf.value='';flagFilters={serious:false,open:false};applyClientFilters()}

applyClientFilters();

</script></body></html>
